def stimulus(rng, cycles):
    rows = []
    reset = 1
    start_stop = 0
    mid = None
    for i in range(cycles):
        if i < 3:
            reset = 1
            start_stop = 0
        elif i == 3:
            reset = 0
            start_stop = 0
        else:
            reset = 0
            if i < 10:
                start_stop = 0
            elif i < 30:
                start_stop = 1
            else:
                r = rng.random()
                if r < 0.05:
                    start_stop = 1 - start_stop
                elif r < 0.08:
                    reset = 1
                else:
                    reset = 0
        row = {'reset': reset, 'start_stop': start_stop}
        if mid is not None:
            row['mid'] = mid
        rows.append(row)
        mid = None
        if i >= 3 and rng.random() < 0.02:
            mid = {'start_stop': 1 - start_stop}
    return rows
